<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class ClaimPayment extends Model{use HasUuids;protected$fillable=['claim_id','claim_decision_id','payee_party_id','amount_minor','currency','status','idempotency_key','external_reference','attempt_count','next_attempt_at','failure_reason','requested_by','approved_by','approved_at','paid_at','reversed_at','claim_settlement_id'];protected function casts():array{return['next_attempt_at'=>'datetime','approved_at'=>'datetime','paid_at'=>'datetime','reversed_at'=>'datetime'];}public function claim():BelongsTo{return$this->belongsTo(Claim::class);}public function decision():BelongsTo{return$this->belongsTo(ClaimDecision::class,'claim_decision_id');}}
